    // In tree mode, the bitmap is full when the root group (last level) is zero.
    size_t rgoff = binfo->levels[binfo->nlevels].group_offset - 1;
    return bitmap[rgoff] == 0;
#else
    // Linear mode: all groups must be zero for the bitmap to be full.
    for (size_t i = 0; i < binfo->ngroups; ++i) {
        if (bitmap[i] != 0) {
            return false;
        }
    }
    return true;
#endif
